// Categories for topic organization
export const topicCategories = {
  faith: { name: "Faith & Spirituality", description: "Deepen your relationship with God" },
  emotions: { name: "Emotions & Mental Health", description: "Find peace and healing" },
  relationships: { name: "Relationships", description: "Build stronger connections" },
  "personal-growth": { name: "Personal Growth", description: "Become your best self" },
  life: { name: "Life & Practical Matters", description: "Navigate daily challenges" },
  health: { name: "Health & Healing", description: "Physical and spiritual wellness" }
};

// Helper function to get verses by topic
export function getVersesByTopic(topic) {
  return versesData[topic] || null;
}

// Helper function to get all topics
export function getAllTopics() {
  return Object.keys(versesData);
}

// Get topic metadata
export function getTopicMetadata(topic) {
  return topicMetadata[topic] || { icon: "📖", color: "from-slate-500 to-gray-600", category: "faith" };
}

// Get topics by category
export function getTopicsByCategory(category) {
  return Object.entries(topicMetadata)
    .filter(([_, meta]) => meta.category === category)
    .map(([topic]) => topic);
}

// Get all categories with their topics
export function getCategorizedTopics() {
  const result = {};
  for (const [category, info] of Object.entries(topicCategories)) {
    result[category] = {
      ...info,
      topics: getTopicsByCategory(category)
    };
  }
  return result;
}

// Get related topics based on category
export function getRelatedTopics(topic, limit = 5) {
  const meta = getTopicMetadata(topic);
  const relatedInCategory = getTopicsByCategory(meta.category)
    .filter(t => t !== topic);
  
  // If not enough in same category, add from other categories
  const allTopics = getAllTopics().filter(t => t !== topic);
  const result = [...relatedInCategory];
  
  for (const t of allTopics) {
    if (!result.includes(t) && result.length < limit) {
      result.push(t);
    }
  }
  
  return result.slice(0, limit);
}

// Get random verse from a topic
export function getRandomVerse(topic) {
  const data = getVersesByTopic(topic);
  if (!data || !data.verses.length) return null;
  return data.verses[Math.floor(Math.random() * data.verses.length)];
}

// Get verse of the day (deterministic based on date)
export function getVerseOfTheDay() {
  const allTopics = getAllTopics();
  const today = new Date();
  const dayOfYear = Math.floor((today - new Date(today.getFullYear(), 0, 0)) / (1000 * 60 * 60 * 24));
  
  const topicIndex = dayOfYear % allTopics.length;
  const topic = allTopics[topicIndex];
  const topicData = getVersesByTopic(topic);
  
  const verseIndex = dayOfYear % topicData.verses.length;
  return {
    ...topicData.verses[verseIndex],
    topic,
    topicTitle: topicData.title
  };
}

// Search verses by text
export function searchVerses(query, limit = 20) {
  const results = [];
  const lowerQuery = query.toLowerCase();
  
  for (const [topic, data] of Object.entries(versesData)) {
    for (const verse of data.verses) {
      if (
        verse.text.toLowerCase().includes(lowerQuery) ||
        verse.reference.toLowerCase().includes(lowerQuery)
      ) {
        results.push({ ...verse, topic, topicTitle: data.title });
        if (results.length >= limit) return results;
      }
    }
  }
  
  return results;
}

// Get total verse count
export function getTotalVerseCount() {
  return Object.values(versesData).reduce((sum, topic) => sum + topic.verses.length, 0);
}